import React, {useState} from "react";
import "./DailyWeather.css";
import axios from "axios";


export default function DailyWeather (props){
let [ready, setReady] = useState(false);
let [data, setData]= useState(null);

    function handleResponse(response){
        console.log(response.data);
      setReady(true);
      setData(response.data);


}


    if (ready){
    return (
    <div className= "DailyWeather">
        <div className="row">
            <div className="col">
                <div className="DailyWeatherDay">Thu</div>
                <div className="DailyWeatherIcon"> <img src={data.daily[0].condition.icon_url}/></div>
                <div className="DailyWeatherTemperature">
                    <span className="max">20º</span>
                    <span className="min">10º</span>
                </div>
                 </div>
                 </div>
                   </div>);} 

                   else {



    let apiKey = "bd75f0b07t2b8413f599c23a504017fo";
    let lat = props.data.latitude;
    let lon = props.data.longitude;
    let apiUrl = `https://api.shecodes.io/weather/v1/forecast?lon=${lon}&lat=${lat}&key=${apiKey}&units=metric`;
    axios.get(apiUrl).then(handleResponse);
    return null;}}
